import{d as l,C as a,o as g,c as h,a3 as e,E as s,j as n,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第八章","description":"《正易心法》第八章——经卦重卦，或离或合：纵横施设有二气老少、三代祖孙、对待、真假、胎甲、错综六种维度，理无不在，故《易》道大。","frontmatter":{"title":"正易心法·第八章","description":"《正易心法》第八章——经卦重卦，或离或合：纵横施设有二气老少、三代祖孙、对待、真假、胎甲、错综六种维度，理无不在，故《易》道大。","category":"guide","aliases":["正易心法第八章","经卦重卦或离或合","纵横施设"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-08.md","filePath":"yijing/zheng-yi-xin-fa/chapter-08.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-08.md"},x=l({...c,setup(u){const o=[{id:"z8-01",label:"一、或离或合",showLabel:!0,sentences:[["经卦重卦，或离或合。",{text:"纵横",glossary:"zongheng"},"施设，理无不在。"]],note:["经卦（三爻的八卦）与重卦（六爻的六十四卦），可以分离也可以组合；纵横排列施设，道理无处不在。（「离」是把重卦拆回上下卦，「合」是把经卦叠成重卦。这是本章的总纲：同一套卦画，可以从许多维度展开。）"]},{id:"z8-02",label:"二、若为诸图",showLabel:!0,sentences:[["纵横，谓若为",{text:"诸图",glossary:"zhutu"},"，"]],note:["所谓「纵横」，是说可以排成各种图式。（「诸图」指陈抟一脉流传的各类易图——河图、洛书、先天图、后天图、太极图等。本章等于在说：这些图不是孤立的，都是同一套卦画的不同展开维度。）"]},{id:"z8-03",label:"三、六种施设",showLabel:!0,sentences:[["或有",{text:"二气老少之渐",glossary:"laoshao"},"，或有",{text:"三代祖孙之别",glossary:"zusun"},"，或有",{text:"对待之理",glossary:"duidai"},"，或有",{text:"真假之义",glossary:"zhenjia"},"，或有",{text:"胎甲之象",glossary:"taijia"},"，或有",{text:"错综之占",glossary:"cuozong"},"。"]],note:["（这六种，就是全部纵横施设的维度：）或有阴阳二气老少渐变的层次（老阳九、少阳七、少阴八、老阴六：九六为动爻，七八为静爻）；或有三代祖孙的卦级区别（经卦为祖、重卦为父、互卦为孙）；或有对立相待的道理（错卦：阴阳全反，如乾与坤、坎与离）；或有真卦假卦的义理（本卦为真，变卦、伏卦为假）；或有胎育萌甲的象（坤为胎、复为甲，阴阳转折最微妙的瞬间）；或有错综变化的占法（错卦阴阳互换、综卦上下翻转）。"]},{id:"z8-04",label:"四、皆具妙理",showLabel:!0,sentences:[["唯其施设，皆具妙理，无所往而不可。"]],note:["这六种施设，每一种都包含妙理，用到哪里都可以。（这是对第四章批评的正面回应：汉儒只用八个字概括八卦，是因为只看到卦的一个维度；这里的六种维度，每一种都有完整的道理。）"]},{id:"z8-05",label:"五、包括万象",showLabel:!0,sentences:[["此所谓包括万象，而《易》道所以大也。"]],note:["这就是所谓「包括万象」，也是《易》道之所以广大的原因。（《系辞传》说《易》道大，是从外部宣告「《易》与天地准」；麻衣说《易》道大，是从内部展示「卦画本身有无穷的展开方式」——前者是结论，后者是推导。）"]}],i=[{id:"zongheng",term:"纵横",pinyin:"zòng héng",meaning:"纵向横向，多维展开。指卦画可从多个维度排列分析。"},{id:"zhutu",term:"诸图",pinyin:"zhū tú",meaning:"各种图式。指陈抟一脉流传的易图：河图、洛书、先天后天八卦图、太极图等。"},{id:"laoshao",term:"二气老少之渐",pinyin:"lǎo shào zhī jiàn",meaning:"阴阳二气老嫩渐变：老阳九、少阳七、少阴八、老阴六。九六为动爻（变），七八为静爻（不变）。"},{id:"zusun",term:"三代祖孙之别",pinyin:"sān dài zǔ sūn",meaning:"经卦→重卦→互卦的层级关系：经卦为祖，重卦为父，互卦为孙。"},{id:"duidai",term:"对待之理",pinyin:"duì dài zhī lǐ",meaning:"卦的对卦（错卦）关系，阴阳完全相反：乾与坤、坎与离、既济与未济。"},{id:"zhenjia",term:"真假之义",pinyin:"zhēn jiǎ zhī yì",meaning:"本卦与变卦、伏卦的关系。真为本卦（当下显现），假为变卦（爻变之后）或伏卦（隐藏的对宫）。"},{id:"taijia",term:"胎甲之象",pinyin:"tāi jiǎ zhī xiàng",meaning:"卦气萌生、潜藏未发的状态：坤为胎（纯阴，阳气全藏），复为甲（一阳来复，初爻生阳）。"},{id:"cuozong",term:"错综之占",pinyin:"cuò zōng zhī zhàn",meaning:"错卦（阴阳互换）与综卦（上下翻转）的占法。占卦时本卦、错卦、综卦可得三个维度的信息。"}];return(b,t)=>{const r=a("DaoTextReading"),d=a("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e(`<h1 id="正易心法·第八章" tabindex="-1">正易心法·第八章 <a class="header-anchor" href="#正易心法·第八章" aria-label="Permalink to &quot;正易心法·第八章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是<strong>方法论总结</strong>，同时开启后续章节的具体展开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前七章（建立认识论）：卦画是本 → 卦脉是理 → 辞外见意 → 观象知天地</span></span>
<span class="line"><span>第八章（方法论总结）：经卦重卦可离可合 → 六种纵横施设 → 理无不在</span></span>
<span class="line"><span>后续（具体展开）：逐一深入六种施设</span></span></code></pre></div><p><strong>核心命题</strong>：《易》道之大，<strong>不在于卦的数量多，而在于同一套卦画可以从无数维度展开，每个维度都有完整的道理。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>六种施设</strong>（纵横的六个维度）：</p><table tabindex="0"><thead><tr><th>施设</th><th>维度</th><th>内容</th></tr></thead><tbody><tr><td><strong>二气老少之渐</strong></td><td>时间轴</td><td>老阳九、少阳七、少阴八、老阴六；九六为动、七八为静</td></tr><tr><td><strong>三代祖孙之别</strong></td><td>层级轴</td><td>经卦（祖）→ 重卦（父）→ 互卦（孙）</td></tr><tr><td><strong>对待之理</strong></td><td>对立轴</td><td>错卦：乾↔坤、坎↔离、既济↔未济</td></tr><tr><td><strong>真假之义</strong></td><td>显隐轴</td><td>真＝本卦；假＝变卦、伏卦</td></tr><tr><td><strong>胎甲之象</strong></td><td>生命轴</td><td>坤为胎（潜藏）、复为甲（萌发）</td></tr><tr><td><strong>错综之占</strong></td><td>变化轴</td><td>错卦（阴阳互换）、综卦（上下翻转）</td></tr></tbody></table><p><strong>「诸图」的历史背景</strong>——麻衣说「若为诸图」，指的是陈抟一脉流传的易图：</p><table tabindex="0"><thead><tr><th>图名</th><th>内容</th><th>对应施设</th></tr></thead><tbody><tr><td>河图</td><td>天地生成数</td><td>二气老少之渐</td></tr><tr><td>洛书</td><td>九宫数字排列</td><td>对待之理</td></tr><tr><td>先天八卦图</td><td>伏羲八卦方位</td><td>三代祖孙／对待</td></tr><tr><td>后天八卦图</td><td>文王八卦方位</td><td>错综之占</td></tr><tr><td>太极图</td><td>阴阳消息圆图</td><td>胎甲之象</td></tr></tbody></table><p><strong>陈抟是这些图的重要传承者（或整理者）</strong>——本章等于在说：<strong>这些图不是孤立的，都是同一套卦画的不同展开维度。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把<strong>六种施设</strong>的名称记住（不必立刻深入）；</li><li>再看<strong>诸图</strong>与六种施设的对应关系；</li><li>记住本章的位置：<strong>前七章说「为什么要看卦画」，第八章说「卦画可以怎么看」，后续说「每种看法具体是什么」。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>或离或合</strong>：重卦可拆回经卦，经卦可叠成重卦。</li><li><strong>纵横施设</strong>：可排成诸图。</li><li><strong>六种维度</strong>：老少之渐、祖孙之别、对待、真假、胎甲、错综。</li><li><strong>理无不在</strong>：每一种施设皆具妙理。</li><li><strong>包括万象</strong>：《易》道之大，在于展开方式无穷。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,16)),s(r,{colophon:"或离或合 · 纵横施设 · 六种维度 · 包括万象",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第八章原文",sections:o,glossary:i}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(d,{items:[{term:"经卦 · 重卦",pinyin:["jīng","guà"],meaning:"经卦是三爻的八卦（基本单元）；重卦是两经卦相叠的六十四卦。「或离」即拆回上下卦，「或合」即叠成重卦。"},{term:"二气老少之渐",pinyin:["lǎo","shào"],meaning:"老阳九、少阳七、少阴八、老阴六。九六为动爻（变），七八为静爻（不变）——这是蓍草筮法与十二消息卦共同的基础。"},{term:"三代祖孙之别",pinyin:["zǔ","sūn"],meaning:"经卦（祖）→ 重卦（父）→ 互卦（孙）。如泰卦：祖为坤乾，父为泰本卦，孙为互卦归妹。"},{term:"对待之理",pinyin:["duì","dài"],meaning:"错卦关系——阴阳完全相反：乾↔坤、坎↔离、既济↔未济。相反相成，是一阴一阳之谓道的卦画体现。"},{term:"真假之义",pinyin:["zhēn","jiǎ"],meaning:"本卦为真（当下显现），变卦与伏卦为假（潜藏或变动之后）。呼应第六章「辞外见意」。"},{term:"胎甲之象",pinyin:["tāi","jiǎ"],meaning:"坤为胎（纯阴，阳气全藏），复为甲（一阳来复，破甲而出）——阴阳由无到有、由隐到显的转折瞬间。"},{term:"错综之占",pinyin:["cuò","zōng"],meaning:"错卦（阴阳互换）、综卦（上下翻转）。占时本卦＋综卦＋错卦，可得当下、对方、反向三个维度。"}]}),t[3]||(t[3]=e(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>全书方法论的枢纽</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前七章（认识论）→ 卦画是本，辞是末；卦脉是天地之理；辞外见意</span></span>
<span class="line"><span>第八章（枢纽）  → 经卦重卦可离可合；六种纵横施设；理无不在</span></span>
<span class="line"><span>第九章以后      → 逐一深入各种施设的具体方法</span></span></code></pre></div><p><strong>第八章等于是「全书的目录的目录」</strong>——前七章说「为什么要看卦画」，第八章说「卦画可以怎么看」，后续章节说「每种看法具体是什么」。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「理无不在」是对第四章批评的正面回应</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第四章（批评）：汉儒执辞忘象，只作八字说（乾健坤顺等）</span></span>
<span class="line"><span>第八章（建构）：卦画有六种维度的展开，每种皆具妙理</span></span></code></pre></div><blockquote><p>汉儒用八个字概括八卦，是因为他们<strong>只看到了卦的一个维度</strong>（义理标签）；麻衣展示了六个维度——这就是「包括万象」与「只作八字说」的本质差距。</p></blockquote><p><strong>与《系辞传》的比较</strong>：</p><table tabindex="0"><thead><tr><th>比较点</th><th>《系辞传》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>《易》道之大的原因</td><td>与天地同准，弥纶天地</td><td>卦画可纵横施设，理无不在</td></tr><tr><td>论证方式</td><td>哲学宣言（直接断言）</td><td>方法论展示（六种维度）</td></tr><tr><td>落脚点</td><td>文字义理</td><td>卦画结构</td></tr><tr><td>可操作性</td><td>需要理解义理</td><td>可以直接操作卦画</td></tr></tbody></table><blockquote><p>《系辞》是<strong>结论</strong>，《正易心法》是<strong>推导</strong>——前者说「《易》与天地同大」，后者展示「卦画本身有无穷的展开方式」。</p></blockquote><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>六种施设先<strong>记住名字</strong>，不必立刻深入；</li><li>把「诸图」与六种施设的对应表看一眼（河图、洛书、先后天图……）；</li><li>带着一个问题往下读：<strong>六种里面，哪一种最贴近我？</strong>（有人重时间（老少之渐），有人重结构（对待），有人重变化（错综））</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>经卦与重卦，可以分离也可以组合；纵横排列施设，道理无处不在。</p><p>所谓「纵横」，是说可以排成各种图式：或有阴阳二气老少渐变的层次；或有三代祖孙的卦级区别；或有对立相待的道理；或有真卦假卦的义理；或有胎育萌甲的象；或有错综变化的占法。</p><p>这六种施设，每一种都包含妙理，用到哪里都可以。</p><p>这就是所谓「包括万象」，也是《易》道之所以广大的原因。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第八章是全书的方法论枢纽——<strong>它不是又讲一条易理，而是把「读卦的六个维度」一次摊开：原来同一套卦画，可以从六个方向看。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>六种施设</strong>——老少之渐（时间）、祖孙之别（层级）、对待（对立）、真假（显隐）、胎甲（生命）、错综（变化）。<strong>我最习惯从哪一维看事？又最缺哪一维？</strong></li><li><strong>「诸图」的定位</strong>——河图、洛书、先天、后天、太极，麻衣说它们不是孤立的，是<strong>同一套卦画的不同展开维度</strong>。这句话我记住了：<strong>图与图之间不是并列，是同一件事的不同光。</strong></li><li><strong>「包括万象」vs「只作八字说」</strong>——这两个说法其实指向同一件事的两面：<strong>限死一个维度，就只剩八个字；放开六个维度，才能包括万象。</strong></li><li><strong>「真假之义」</strong>——真为显象，假为伏象。<strong>这里的「假」是「虚假」还是「假借」？</strong> 我先记下，等后续章节回答。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>老一辈为什么是老阳 9、少阳 7、少阴 8、老阴 6？</strong> 表面看是筮法（大衍五十、四营十八变）算出来的；但更深一层，它出自<strong>河图天地之数</strong>——<strong>9 是阳数之极，7 是阳数之少；6 是老阴，8 是少阴</strong>。<strong>「老」是气的完成态，「少」是气的初生态——老则变，少则静。</strong> 这也正是《周易》爻辞用「九」称阳爻、「六」称阴爻的原因：<strong>取的正是「老」这两个完成态的数。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 「只作八字说」之弊（本章是正面建构）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-05">第五章 · 无穷妙义</a> — 「合为自然」（本章是其展开维度）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-06">第六章 · 消息卦画</a> — 「真假之义」与「辞外见意」相通</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 八卦的物象与卦德（本章说八物只是「宗本」，非全部）</li></ul>`,25))])}}});export{y as __pageData,x as default};
